                            "host_note":  "WM_GETOBJECT hook on a Panel child, same mechanism as ScratchForms.cs AutomationIdProvider/AutomationIdWindow, extended with IGridItemProvider + ITableItemProvider",
                            "containing_grid_is_self":  true,
                            "cell":  {
