use agent_desktop_core::{AppError, CursorImage, CursorOverlayStyle, Point};
use clap::Args;
use std::path::PathBuf;

#[derive(Args, Debug, Default)]
pub(crate) struct CursorOverlayImagesArgs {
    #[arg(
        long,
        value_name = "PATH",
        help = "Draw the cursor from a PNG file instead of the built-in arrow; scaled by --size"
    )]
    pub image: Option<PathBuf>,
    #[arg(
        long,
        value_name = "X,Y",
        requires = "image",
        value_parser = parse_hotspot,
        help = "Point in the image, in image points from its top-left, that marks the click position (default 0,0)"
    )]
    pub hotspot: Option<(f64, f64)>,
    #[arg(
        long,
        value_name = "PATH",
        help = "PNG shown instead while the cursor rests on a button, link or other pressable control"
    )]
    pub pointer_image: Option<PathBuf>,
    #[arg(
        long,
        value_name = "X,Y",
        requires = "pointer_image",
        value_parser = parse_hotspot,
        help = "Click point in the pointer image, in image points from its top-left (default 0,0)"
    )]
    pub pointer_hotspot: Option<(f64, f64)>,
}

impl CursorOverlayImagesArgs {
    pub(crate) fn apply_to(&self, style: &mut CursorOverlayStyle) -> Result<(), AppError> {
        style.set_image(cursor_image(self.image.as_deref(), self.hotspot)?);
        style.set_pointer_image(cursor_image(
            self.pointer_image.as_deref(),
            self.pointer_hotspot,
        )?);
        Ok(())
    }
}

fn cursor_image(
    path: Option<&std::path::Path>,
    hotspot: Option<(f64, f64)>,
) -> Result<Option<CursorImage>, AppError> {
    let Some(path) = path else {
        return Ok(None);
    };
    let resolved = std::fs::canonicalize(path).map_err(|error| {
        AppError::invalid_input(format!(
            "Cursor image '{}' cannot be read: {error}",
            path.display()
        ))
    })?;
    let resolved = resolved
        .into_os_string()
        .into_string()
        .map_err(|_| AppError::invalid_input("Cursor image path must be valid UTF-8"))?;
    let (x, y) = hotspot.unwrap_or((0.0, 0.0));
    let image = CursorImage::new(resolved, Point { x, y })?;
    image.verify_file()?;
    Ok(Some(image))
}

fn parse_hotspot(value: &str) -> Result<(f64, f64), String> {
    let invalid = || "hotspot must be X,Y in image points, e.g. 4,2".to_string();
    let (x, y) = value.split_once(',').ok_or_else(invalid)?;
    let x = x.trim().parse::<f64>().map_err(|_| invalid())?;
    let y = y.trim().parse::<f64>().map_err(|_| invalid())?;
    Ok((x, y))
}

use crate::{AdapterError, ErrorCode, Point};
use serde::{Deserialize, Serialize};
use std::io::Read;
#[cfg(unix)]
use std::os::unix::fs::OpenOptionsExt;
use std::path::Path;

pub const MAX_CURSOR_IMAGE_PATH_BYTES: usize = 1024;
pub const MAX_CURSOR_IMAGE_BYTES: u64 = 2 * 1024 * 1024;
/// Largest PNG pixel width or height the renderer will decode.
pub const MAX_CURSOR_IMAGE_PIXELS: u32 = 1024;
const PNG_HEADER_BYTES: usize = 24;
const MAX_HOTSPOT: f64 = 512.0;
const PNG_MAGIC: &[u8] = b"\x89PNG\r\n\x1a\n";

/// A PNG drawn in place of the built-in cursor arrow. `hotspot` is the
/// click point in image points from the image's top-left corner.
#[derive(Debug, Clone, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct CursorImage {
    path: String,
    #[serde(default = "origin", skip_serializing_if = "is_origin")]
    hotspot: Point,
}

impl CursorImage {
    pub fn new(path: String, hotspot: Point) -> Result<Self, AdapterError> {
        Self { path, hotspot }.validated()
    }

    pub fn validated(self) -> Result<Self, AdapterError> {
        if self.path.is_empty() || self.path.contains('\0') {
            return Err(invalid("Cursor image path must be a non-empty file path"));
        }
        if escaped_len(&self.path) > MAX_CURSOR_IMAGE_PATH_BYTES {
            return Err(invalid(format!(
                "Cursor image path must be at most {MAX_CURSOR_IMAGE_PATH_BYTES} bytes once JSON-escaped"
            )));
        }
        if !Path::new(&self.path).is_absolute() {
            return Err(invalid("Cursor image path must be absolute"));
        }
        if !Path::new(&self.path)
            .extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| extension.eq_ignore_ascii_case("png"))
        {
            return Err(invalid("cursor images must be PNG"));
        }
        let within = |value: f64| value.is_finite() && (0.0..=MAX_HOTSPOT).contains(&value);
        if !within(self.hotspot.x) || !within(self.hotspot.y) {
            return Err(invalid(format!(
                "Cursor image --hotspot must be between 0 and {MAX_HOTSPOT} on both axes"
            )));
        }
        Ok(self)
    }

    /// Checks that the file is a regular file within the size limit, carries the PNG
    /// signature and declares at most
    /// [`MAX_CURSOR_IMAGE_PIXELS`] per side. Every check reads the same open file.
    pub fn verify_file(&self) -> Result<(), AdapterError> {
        let unreadable = |error: std::io::Error| {
            invalid(format!("Cursor image '{}' cannot be read", self.path))
                .with_platform_detail(error.to_string())
        };
        let mut options = std::fs::OpenOptions::new();
        options.read(true);
        #[cfg(unix)]
        options.custom_flags(libc::O_NONBLOCK);
        let mut file = options.open(&self.path).map_err(unreadable)?;
        let metadata = file.metadata().map_err(unreadable)?;
        if !metadata.is_file() {
            return Err(invalid(format!(
                "Cursor image '{}' is not a regular file",
                self.path
            )));
        }
        if metadata.len() > MAX_CURSOR_IMAGE_BYTES {
            return Err(invalid(format!(
                "Cursor image must be at most {} MiB",
                MAX_CURSOR_IMAGE_BYTES / (1024 * 1024)
            )));
        }
        let mut header = [0; PNG_HEADER_BYTES];
        file.read_exact(&mut header[..PNG_MAGIC.len()])
            .map_err(unreadable)?;
        if !header.starts_with(PNG_MAGIC) {
            return Err(invalid("cursor images must be PNG"));
        }
        file.read_exact(&mut header[PNG_MAGIC.len()..])
            .map_err(unreadable)?;
        if !png_dimensions_fit(&header) {
            return Err(invalid(format!(
                "Cursor image PNG must be at most {MAX_CURSOR_IMAGE_PIXELS} pixels per side"
            )));
        }
        Ok(())
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub const fn hotspot(&self) -> &Point {
        &self.hotspot
    }
}

fn png_dimensions_fit(header: &[u8]) -> bool {
    let side = |at: usize| {
        header
            .get(at..at + 4)
            .and_then(|bytes| bytes.try_into().ok())
            .map(u32::from_be_bytes)
    };
    matches!(
        (header.get(12..16), side(16), side(20)),
        (Some(b"IHDR"), Some(width), Some(height))
            if (1..=MAX_CURSOR_IMAGE_PIXELS).contains(&width)
                && (1..=MAX_CURSOR_IMAGE_PIXELS).contains(&height)
    )
}

fn escaped_len(value: &str) -> usize {
    serde_json::to_string(value).map_or(usize::MAX, |json| json.len().saturating_sub(2))
}

const fn origin() -> Point {
    Point { x: 0.0, y: 0.0 }
}

fn is_origin(point: &Point) -> bool {
    *point == origin()
}

fn invalid(message: impl Into<String>) -> AdapterError {
    AdapterError::new(ErrorCode::InvalidArgs, message)
}

use super::CursorImage;
use crate::AdapterError;
use serde::{Deserialize, Serialize};

/// Custom cursor artwork: `arrow` is drawn while the cursor travels and rests, `pointer` once
/// it arrives on a pressable control. Either may be absent; a missing arrow falls back to the
/// built-in cursor, a missing pointer keeps the arrow.
#[derive(Debug, Clone, Default, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct CursorImages {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    arrow: Option<CursorImage>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pointer: Option<CursorImage>,
}

impl CursorImages {
    pub const fn is_empty(&self) -> bool {
        self.arrow.is_none() && self.pointer.is_none()
    }

    pub fn validated(self) -> Result<Self, AdapterError> {
        Ok(Self {
            arrow: self.arrow.map(CursorImage::validated).transpose()?,
            pointer: self.pointer.map(CursorImage::validated).transpose()?,
        })
    }

    pub fn set_arrow(&mut self, arrow: Option<CursorImage>) {
        self.arrow = arrow;
    }

    pub fn set_pointer(&mut self, pointer: Option<CursorImage>) {
        self.pointer = pointer;
    }

    pub const fn arrow(&self) -> Option<&CursorImage> {
        self.arrow.as_ref()
    }

    pub const fn pointer(&self) -> Option<&CursorImage> {
        self.pointer.as_ref()
    }
}

use crate::ImageFormat;

#[derive(Debug)]
pub struct ImageBuffer {
    pub data: Vec<u8>,
    pub format: ImageFormat,
    pub width: u32,
    pub height: u32,
    pub scale_factor: f64,
}

pub const MAX_PNG_INPUT_BYTES: usize = 64 * 1024 * 1024;
const MAX_PNG_PIXELS: u64 = 64 * 1024 * 1024;
const PNG_SIGNATURE: &[u8; 8] = b"\x89PNG\r\n\x1a\n";
const PNG_HEADER_BYTES: usize = 33;

pub fn parse_png_dimensions(data: &[u8]) -> Option<(u32, u32)> {
    if data.len() < PNG_HEADER_BYTES || data.len() > MAX_PNG_INPUT_BYTES {
        return None;
    }
    if data.get(..PNG_SIGNATURE.len())? != PNG_SIGNATURE {
        return None;
    }
    if read_u32(data, 8)? != 13 || data.get(12..16)? != b"IHDR" {
        return None;
    }
    let width = read_u32(data, 16)?;
    let height = read_u32(data, 20)?;
    let depth = *data.get(24)?;
    let color = *data.get(25)?;
    valid_png_header(width, height, depth, color, data.get(26..29)?).then_some((width, height))
}

fn read_u32(data: &[u8], offset: usize) -> Option<u32> {
    Some(u32::from_be_bytes(
        data.get(offset..offset.checked_add(4)?)?.try_into().ok()?,
    ))
}

fn valid_png_header(width: u32, height: u32, depth: u8, color: u8, tail: &[u8]) -> bool {
    let valid_depth = match color {
        0 => matches!(depth, 1 | 2 | 4 | 8 | 16),
        2 | 4 | 6 => matches!(depth, 8 | 16),
        3 => matches!(depth, 1 | 2 | 4 | 8),
        _ => false,
    };
    let pixels = u64::from(width).checked_mul(u64::from(height));
    width > 0
        && height > 0
        && pixels.is_some_and(|pixels| pixels <= MAX_PNG_PIXELS)
        && valid_depth
        && matches!(tail, [0, 0, 0 | 1])
}

#[cfg(test)]
mod tests {
    use super::*;

    fn one_pixel_png() -> Vec<u8> {
        vec![
            137, 80, 78, 71, 13, 10, 26, 10, 0, 0, 0, 13, 73, 72, 68, 82, 0, 0, 0, 1, 0, 0, 0, 1,
            8, 4, 0, 0, 0, 181, 28, 12, 2, 0, 0, 0, 11, 73, 68, 65, 84, 120, 218, 99, 100, 248, 15,
            0, 1, 5, 1, 1, 39, 24, 227, 102, 0, 0, 0, 0, 73, 69, 78, 68, 174, 66, 96, 130,
        ]
    }

    #[test]
    fn decodes_valid_png_before_returning_dimensions() {
        let bytes = one_pixel_png();

        assert_eq!(parse_png_dimensions(&bytes), Some((1, 1)));
    }

    #[test]
    fn accepts_adam7_interlaced_png_header() {
        let mut bytes = one_pixel_png();
        bytes[28] = 1;

        assert_eq!(parse_png_dimensions(&bytes), Some((1, 1)));
    }

    #[test]
    fn rejects_unknown_png_interlace_method() {
        let mut bytes = one_pixel_png();
        bytes[28] = 2;

        assert_eq!(parse_png_dimensions(&bytes), None);
    }

    #[test]
    fn rejects_undersized_buffer() {
        assert_eq!(parse_png_dimensions(&[1, 2, 3]), None);
    }

    #[test]
    fn rejects_buffer_with_wrong_signature() {
        let mut bytes = one_pixel_png();
        bytes[0] = 0x00;

        assert_eq!(parse_png_dimensions(&bytes), None);
    }

    #[test]
    fn metadata_parse_does_not_duplicate_platform_payload_validation() {
        let mut bytes = one_pixel_png();
        bytes[45] ^= 0xff;

        assert_eq!(parse_png_dimensions(&bytes), Some((1, 1)));
    }

    #[test]
    fn rejects_header_only_png() {
        let bytes = one_pixel_png();

        assert_eq!(parse_png_dimensions(&bytes[..24]), None);
    }
}

#[derive(Debug)]
pub enum ImageFormat {
    Png,
    Jpg,
}

impl ImageFormat {
    pub fn as_str(&self) -> &'static str {
        match self {
            ImageFormat::Png => "png",
            ImageFormat::Jpg => "jpg",
        }
    }
}
